whenever sqlerror exit sql.sqlcode rollback
set define off
connect -name IMART
declare
  l_css clob := q'~body:has(.imart-home-shell){background:#f4f7fc}body:has(.imart-home-shell)::before{content:none!important;display:none!important}.imart-home-region,.imart-home-region .t-Region-body,.imart-home-region .t-Region-wrap{background:transparent!important;border:0!important;box-shadow:none!important}.imart-home-region .t-Region-header{display:none!important}.imart-home-region .t-Region-body{padding:0!important}.imart-home-shell{--ink:#17213d;--muted:#66738f;--line:#e3e9f4;--blue:#2854d9;max-width:1520px;margin:0 auto;padding:26px 24px 42px;color:var(--ink);font-family:Inter,"Segoe UI",sans-serif}.imart-home-hero{position:relative;isolation:isolate;min-height:325px;overflow:hidden;border-radius:24px;padding:42px 46px;display:grid;grid-template-columns:minmax(0,.95fr) minmax(390px,1.05fr);align-items:center;background:linear-gradient(123deg,#112b71 0%,#3155c7 47%,#705ee7 100%);box-shadow:0 20px 45px rgba(38,61,148,.22)}.imart-home-hero:before{content:"";position:absolute;z-index:-1;width:470px;height:470px;left:-175px;bottom:-320px;border:1px solid rgba(255,255,255,.20);border-radius:50%;box-shadow:0 0 0 48px rgba(255,255,255,.045),0 0 0 97px rgba(255,255,255,.04)}.imart-home-hero:after{content:"";position:absolute;z-index:-1;inset:0;background:radial-gradient(circle at 71% 8%,rgba(179,209,255,.50),transparent 28%),linear-gradient(90deg,rgba(6,18,58,.25),transparent 65%)}.imart-home-copy{position:relative;z-index:2;max-width:630px}.imart-home-eyebrow{margin:0 0 16px;display:inline-flex;align-items:center;gap:9px;padding:8px 12px;border:1px solid rgba(255,255,255,.28);border-radius:999px;color:#fff;background:rgba(255,255,255,.11);font-weight:700;font-size:12px;letter-spacing:.07em;text-transform:uppercase}.imart-home-eyebrow:before{content:"";width:8px;height:8px;border-radius:50%;background:#77f0ce;box-shadow:0 0 0 4px rgba(119,240,206,.15)}.imart-home-hero h1{color:#fff;font-size:clamp(30px,3vw,48px);line-height:1.08;letter-spacing:-.045em;margin:0 0 13px;font-weight:800}.imart-home-hero p{margin:0;max-width:560px;color:rgba(243,247,255,.83);line-height:1.65;font-size:16px}.imart-home-hero-actions{display:flex;flex-wrap:wrap;gap:11px;margin-top:26px}.imart-home-primary,.imart-home-secondary{display:inline-flex;align-items:center;gap:9px;text-decoration:none;font-weight:750;font-size:14px;border-radius:10px;padding:12px 16px;transition:transform .18s ease}.imart-home-primary{color:#1d2b62;background:#fff;box-shadow:0 7px 18px rgba(6,17,55,.18)}.imart-home-secondary{color:#fff;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.08)}.imart-home-primary:hover,.imart-home-secondary:hover{transform:translateY(-2px)}.imart-home-hero-art{position:absolute;pointer-events:none;z-index:1;right:0;inset-block:0;width:58%;display:flex;align-items:flex-end}.imart-home-hero-art img{width:100%;height:100%;object-fit:cover;object-position:right center;mix-blend-mode:screen;opacity:.86;mask-image:linear-gradient(90deg,transparent 0%,black 23%,black 100%)}.imart-home-meta{position:absolute;z-index:3;right:31px;bottom:25px;display:flex;gap:9px}.imart-home-meta span{color:#ecf1ff;font-size:12px;font-weight:650;padding:7px 10px;border-radius:8px;background:rgba(10,24,76,.35);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.16)}.imart-home-section{margin-top:24px;padding:25px;border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 10px 25px rgba(27,47,96,.055)}.imart-home-section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:20px}.imart-home-section h2{margin:0;font-size:19px;line-height:1.2;letter-spacing:-.025em}.imart-home-section-head p{margin:5px 0 0;color:var(--muted);font-size:13px}.imart-home-section-link{color:var(--blue);font-size:13px;font-weight:750;text-decoration:none;white-space:nowrap}.imart-home-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.imart-home-card{position:relative;min-height:139px;padding:18px;overflow:hidden;display:flex;flex-direction:column;align-items:flex-start;text-decoration:none;color:var(--ink);border:1px solid #e3e8f2;border-radius:15px;background:linear-gradient(180deg,#fff,#fbfcff);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease}.imart-home-card:hover{transform:translateY(-4px);border-color:#b8c7f6;box-shadow:0 14px 25px rgba(47,73,155,.12)}.imart-home-card-icon{width:40px;height:40px;display:grid;place-items:center;color:var(--accent,#2854d9);border-radius:12px;background:var(--wash,#edf2ff);font-size:18px}.imart-home-card h3{margin:17px 0 5px;font-size:14px}.imart-home-card p{margin:0;color:var(--muted);font-size:12px;line-height:1.45}.imart-home-card-arrow{position:absolute;right:16px;bottom:15px;color:var(--accent,#2854d9);font-size:18px}.imart-home-card--teal{--accent:#078e91;--wash:#e8f8f7}.imart-home-card--amber{--accent:#cd7a08;--wash:#fff6e5}.imart-home-card--rose{--accent:#dc476a;--wash:#fff0f3}.imart-home-card--purple{--accent:#6a53e6;--wash:#f0edff}.imart-home-lower{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(340px,.8fr);gap:24px;margin-top:24px}.imart-home-focus{padding:24px;border-radius:18px;color:#eef3ff;background:linear-gradient(135deg,#172d6d,#273e91);box-shadow:0 12px 28px rgba(24,47,120,.16)}.imart-home-focus .imart-home-kicker{color:#9db9ff;font-size:12px;font-weight:750;letter-spacing:.08em;text-transform:uppercase}.imart-home-focus h2{margin:9px 0 8px;color:#fff;font-size:22px}.imart-home-focus p{margin:0;color:#c9d5fa;font-size:14px;line-height:1.6}.imart-home-focus-links{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:20px}.imart-home-focus-links a{display:flex;align-items:center;justify-content:space-between;min-height:48px;padding:0 12px;color:#fff;text-decoration:none;font-size:13px;font-weight:700;border:1px solid rgba(255,255,255,.17);border-radius:10px;background:rgba(255,255,255,.08)}.imart-home-day{padding:24px;border:1px solid var(--line);border-radius:18px;background:#fff}.imart-home-day h2{margin:0 0 7px;font-size:19px}.imart-home-day>p{margin:0;color:var(--muted);font-size:13px;line-height:1.55}.imart-home-day-list{margin:18px 0 0;padding:0;list-style:none}.imart-home-day-list li{display:flex;align-items:center;gap:10px;padding:11px 0;border-top:1px solid #eef1f6;color:#43506d;font-size:13px;font-weight:650}.imart-home-day-list i{width:23px;height:23px;display:grid;place-items:center;color:#0d9984;border-radius:50%;background:#e7f8f2;font-size:11px}@media(max-width:1100px){.imart-home-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.imart-home-hero{grid-template-columns:1fr}.imart-home-hero-art{width:60%;opacity:.5}.imart-home-lower{grid-template-columns:1fr}}@media(max-width:680px){.imart-home-shell{padding:14px 12px 26px}.imart-home-hero{min-height:390px;padding:30px 24px;border-radius:18px}.imart-home-hero-art{width:100%;opacity:.32}.imart-home-meta{right:18px;bottom:17px}.imart-home-section{padding:18px;border-radius:15px}.imart-home-grid{grid-template-columns:1fr}.imart-home-section-head{flex-direction:column}.imart-home-focus-links{grid-template-columns:1fr}}~';
  l_html clob := q'~<main class="imart-home-shell" aria-label="InfoMart operations workspace"><section class="imart-home-hero"><div class="imart-home-copy"><div class="imart-home-eyebrow">Operations workspace</div><h1>Make every movement<br>matter.</h1><p>One calm starting point for purchasing, incoming goods and inventory operations—built to help you move from plan to action without the clutter.</p><div class="imart-home-hero-actions"><a class="imart-home-primary" href="f?p=&APP_ID.:117:&APP_SESSION.::::">Open purchase orders <span aria-hidden="true">→</span></a><a class="imart-home-secondary" href="f?p=&APP_ID.:145:&APP_SESSION.::::">View GRN register <span aria-hidden="true">↗</span></a></div></div><div class="imart-home-hero-art"><img src="#APP_FILES#imart-home-operations-hero.png" alt=""></div><div class="imart-home-meta"><span>IMART workspace</span><span>FY 26–27</span></div></section><section class="imart-home-section"><div class="imart-home-section-head"><div><h2>Start where the work is</h2><p>Direct access to the operational registers your team uses every day.</p></div><a class="imart-home-section-link" href="f?p=&APP_ID.:117:&APP_SESSION.::::">Browse purchasing →</a></div><div class="imart-home-grid"><a class="imart-home-card" href="f?p=&APP_ID.:117:&APP_SESSION.::::"><span class="imart-home-card-icon">▣</span><h3>Purchase orders</h3><p>Create, review and track supplier commitments.</p><span class="imart-home-card-arrow">→</span></a><a class="imart-home-card imart-home-card--teal" href="f?p=&APP_ID.:145:&APP_SESSION.::::"><span class="imart-home-card-icon">⇣</span><h3>Goods receipt notes</h3><p>Receive materials and keep the inbound flow moving.</p><span class="imart-home-card-arrow">→</span></a><a class="imart-home-card imart-home-card--amber" href="f?p=&APP_ID.:142:&APP_SESSION.::::"><span class="imart-home-card-icon">◫</span><h3>Purchase bills</h3><p>Review bills with the right purchasing context.</p><span class="imart-home-card-arrow">→</span></a><a class="imart-home-card imart-home-card--purple" href="f?p=&APP_ID.:407:&APP_SESSION.::::"><span class="imart-home-card-icon">◈</span><h3>Stock statement</h3><p>See inventory positions when you need them.</p><span class="imart-home-card-arrow">→</span></a><a class="imart-home-card imart-home-card--rose" href="f?p=&APP_ID.:68:&APP_SESSION.::::"><span class="imart-home-card-icon">⇢</span><h3>Material in</h3><p>Follow every inbound material movement.</p><span class="imart-home-card-arrow">→</span></a><a class="imart-home-card imart-home-card--teal" href="f?p=&APP_ID.:129:&APP_SESSION.::::"><span class="imart-home-card-icon">✓</span><h3>Requisitions</h3><p>Move approved requirements into procurement.</p><span class="imart-home-card-arrow">→</span></a><a class="imart-home-card imart-home-card--amber" href="f?p=&APP_ID.:107:&APP_SESSION.::::"><span class="imart-home-card-icon">⌁</span><h3>Indent register</h3><p>Keep demand intake visible and accountable.</p><span class="imart-home-card-arrow">→</span></a><a class="imart-home-card imart-home-card--purple" href="f?p=&APP_ID.:151:&APP_SESSION.::::"><span class="imart-home-card-icon">▤</span><h3>Bill pass</h3><p>Route purchase bill passes with confidence.</p><span class="imart-home-card-arrow">→</span></a></div></section><div class="imart-home-lower"><section class="imart-home-focus"><div class="imart-home-kicker">Workflow launcher</div><h2>Keep the inbound cycle moving</h2><p>Use the flow that matches the next decision your team needs to make.</p><div class="imart-home-focus-links"><a href="f?p=&APP_ID.:118:&APP_SESSION.::::">New PO <span>→</span></a><a href="f?p=&APP_ID.:146:&APP_SESSION.::::">New GRN <span>→</span></a><a href="f?p=&APP_ID.:143:&APP_SESSION.::::">New bill <span>→</span></a></div></section><aside class="imart-home-day"><h2>Your workspace, ready</h2><p>Choose a register above to continue a workflow or create a new document from the launcher.</p><ul class="imart-home-day-list"><li><i>✓</i>Shortcuts lead to the live IMART pages</li><li><i>✓</i>Designed for focused, low-friction work</li><li><i>✓</i>Your role determines available actions</li></ul></aside></div></main>~';
begin
  update apex_260100.wwv_flow_steps
     set step_title = 'InfoMart | Operations workspace', inline_css = l_css, last_updated_on = sysdate
   where flow_id = 105 and id = 1 and security_group_id = 4744311978888504;
  if sql%rowcount <> 1 then raise_application_error(-20001, 'Home page CSS was not updated'); end if;
  update apex_260100.wwv_flow_page_plugs
     set plug_source = l_html, region_css_classes = 'imart-home-region', plug_display_point = 'BODY', plug_template = 4072358936313175081, region_template_options = '#DEFAULT#:t-Region--noPadding:t-Region--noUI', last_updated_on = sysdate
   where flow_id = 105 and page_id = 1 and static_id = 'iron-mart' and security_group_id = 4744311978888504;
  if sql%rowcount <> 1 then raise_application_error(-20002, 'Home dashboard region was not updated'); end if;
end;
/
commit;
begin
  wwv_flow_imp.component_begin(p_version_yyyy_mm_dd=>'2026.03.30',p_release=>'26.1.2',p_default_workspace_id=>4744311978888504,p_default_application_id=>105,p_default_id_offset=>7541489808702750,p_default_owner=>'IMART');
  wwv_flow_imp_shared.clear_cache;
  wwv_flow_imp.component_end;
end;
/
commit;
exit
